用户态管理的线程创建

    pub fn spawn(&mut self, f: fn()) { // f函数是线程入口
        let available = self  
            .tasks.itermut()  //遍历队列中的任务
            .find(|t| t.state == State::Available) //查找可用的任务
            .expect("no available task.");
        let size = available.stack.len();
        unsafe {
            let sptr = available.stack.asmutptr().offset(size as isize);
            let sptr = (sptr as usize & !7) as mut u8; // 栈按8字节对齐
            available.ctx.x1 = guard as u64;  //ctx.x1  is old return address
            available.ctx.nx1 = f as u64;     //ctx.nx2 is new return address
            available.ctx.x2 = sptr.offset(-32) as u64; //cxt.x2 is sp
        }
        available.state = State::Ready; //设置任务为就绪态
    }

fn guard() {
    unsafe {
        let rtptr = RUNTIME as mut Runtime;
        (rtptr).treturn();
    };
}
fn treturn(&mut self) {
    if self.current != 0 {
        self.tasks[self.current].state = State::Available;
        self.tyield();
    }
}
guard函数意味着传入的f函数（线程的主体）已经返回，线程已完成运行任务，进而取消引用我们的运行时并调用treturn()。

